package org.sleepmonitor.app;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
public class MainActivity extends Activity{
 TextView values; Graph graph; Handler h=new Handler(); File selected;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,64,24,32);ScrollView scroll=new ScrollView(this);scroll.addView(l);setContentView(scroll);TextView title=new TextView(this);title.setText("SleepMonitor 1.2");title.setTextSize(30);l.addView(title);values=new TextView(this);values.setTextSize(23);l.addView(values);graph=new Graph();l.addView(graph,new LinearLayout.LayoutParams(-1,320));button(l,"Aufzeichnung starten",()->{if(permissions())startForegroundService(new Intent(this,MonitorService.class));});button(l,"Aufzeichnung stoppen",()->stopService(new Intent(this,MonitorService.class)));button(l,"CSV exportieren",this::choose);button(l,"Smart Band 7 – BLE Diagnose",()->{if(permissions())bandTest();});TextView note=new TextView(this);note.setText("Experimentelle Aufzeichnung – kein medizinischer Alarm. Lagesensor noch nicht integriert. Messdaten bleiben lokal. Für die Messung andere Oximeter-Apps trennen.");l.addView(note);h.post(refresh);}
 void button(LinearLayout l,String s,Runnable r){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->r.run());l.addView(b);}
 boolean permissions(){ArrayList<String> p=new ArrayList<>();if(Build.VERSION.SDK_INT>=31){p.add("android.permission.BLUETOOTH_SCAN");p.add("android.permission.BLUETOOTH_CONNECT");}else p.add("android.permission.ACCESS_FINE_LOCATION");if(Build.VERSION.SDK_INT>=33)p.add("android.permission.POST_NOTIFICATIONS");ArrayList<String> missing=new ArrayList<>();for(String x:p)if(checkSelfPermission(x)!=PackageManager.PERMISSION_GRANTED)missing.add(x);if(!missing.isEmpty()){requestPermissions(missing.toArray(new String[0]),1);return false;}return true;}
 final Runnable refresh=new Runnable(){public void run(){boolean fresh=MonitorService.running&&System.currentTimeMillis()-MonitorService.last<3000;values.setText(MonitorService.status+"\nSpO₂: "+(fresh&&MonitorService.oxygen>0?MonitorService.oxygen+" %":"–")+"\nPuls: "+(fresh&&MonitorService.pulse>0?MonitorService.pulse+" bpm":"–")+"\nAkku: "+(fresh&&MonitorService.battery>=0?MonitorService.battery+" %":"–"));long seconds=MonitorService.started==0?0:(SystemClock.elapsedRealtime()-MonitorService.started)/1000;values.append("\nLaufzeit: "+String.format(Locale.US,"%02d:%02d:%02d",seconds/3600,(seconds/60)%60,seconds%60)+"\nEmpfangen: "+MonitorService.received+" | CSV-Zeilen: "+MonitorService.saved+"\nSpeicher: "+MonitorService.storage+"\nLetzte Speicherung: "+(MonitorService.lastSaved==0?"–":new java.text.SimpleDateFormat("HH:mm:ss",Locale.US).format(new Date(MonitorService.lastSaved)))+"\nBLE-Neuverbindungen: "+MonitorService.disconnects);graph.invalidate();h.postDelayed(this,500);}};
 void choose(){File[] fs=new File(getFilesDir(),"records").listFiles();if(fs==null||fs.length==0){Toast.makeText(this,"Keine Aufzeichnungen",0).show();return;}Arrays.sort(fs,Comparator.comparingLong(File::lastModified).reversed());String[] names=new String[fs.length];for(int i=0;i<fs.length;i++)names[i]=fs[i].getName();new AlertDialog.Builder(this).setTitle("Aufzeichnung auswählen").setItems(names,(d,i)->{selected=fs[i];Intent in=new Intent(Intent.ACTION_CREATE_DOCUMENT);in.setType("text/csv");in.addCategory(Intent.CATEGORY_OPENABLE);in.putExtra(Intent.EXTRA_TITLE,selected.getName());startActivityForResult(in,2);}).show();}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==2&&c==RESULT_OK&&d!=null&&selected!=null){try(InputStream in=new FileInputStream(selected);OutputStream out=getContentResolver().openOutputStream(d.getData())){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);Toast.makeText(this,"CSV gespeichert",0).show();}catch(Exception e){Toast.makeText(this,"Export fehlgeschlagen",1).show();}}}
 BandProbe probe;
 void bandTest(){if(probe!=null)probe.close();EditText mac=new EditText(this);mac.setSingleLine();mac.setText("D1:01:50:2A:4A:EC");new AlertDialog.Builder(this).setTitle("Smart Band 7 Adresse").setView(mac).setNegativeButton("Abbrechen",null).setPositiveButton("Verbinden",(d,w)->{TextView output=new TextView(this);output.setTextIsSelectable(true);ScrollView s=new ScrollView(this);s.addView(output);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("BLE Diagnose").setView(s).setPositiveButton("Trennen",null).create();probe=new BandProbe(this,msg->runOnUiThread(()->output.append(msg+"\n")));dialog.setOnDismissListener(x->{if(probe!=null){probe.close();probe=null;}});dialog.show();probe.start(mac.getText().toString().trim());}).show();}
 protected void onDestroy(){if(probe!=null)probe.close();h.removeCallbacksAndMessages(null);super.onDestroy();}
 class Graph extends View{Paint p=new Paint(3);Graph(){super(MainActivity.this);}protected void onDraw(Canvas c){float w=getWidth(),ht=getHeight();p.setTextSize(24);for(int y=70;y<=100;y+=10){float yy=20+(100-y)*(ht-45)/30;p.setColor(Color.GRAY);c.drawText(""+y,0,yy+8,p);c.drawLine(45,yy,w,yy,p);}ArrayList<Integer> a;synchronized(MonitorService.history){a=new ArrayList<>(MonitorService.history);}p.setColor(Color.GREEN);p.setStrokeWidth(4);for(int i=1;i<a.size();i++){float x1=45+(i-1)*(w-50)/299,x2=45+i*(w-50)/299;float y1=20+(100-Math.max(70,a.get(i-1)))*(ht-45)/30,y2=20+(100-Math.max(70,a.get(i)))*(ht-45)/30;c.drawLine(x1,y1,x2,y2,p);}}}
}